package main

import (
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

func main() {
	data, _ := os.ReadFile("/dev/stdin")
	s := strings.TrimSpace(string(data))
	if s == "" {
		return
	}
	parts := strings.Fields(s)
	N, _ := strconv.Atoi(parts[0])
	P := parseProb(parts[1])
	if P <= 0 {
		fmt.Println(0)
		return
	}
	if P >= 1 {
		fmt.Println(N - 1)
		return
	}
	low, high := 0, N
	for low < high {
		mid := (low + high) / 2
		prob := calcProb(N, mid)
		if prob >= P-1e-12 {
			high = mid
		} else {
			low = mid + 1
		}
	}
	fmt.Println(low)
}

func parseProb(s string) float64 {
	if strings.Contains(s, ".") {
		parts := strings.Split(s, ".")
		intPart := parts[0]
		fracPart := parts[1]
		for len(fracPart) < 4 {
			fracPart += "0"
		}
		if len(fracPart) > 4 {
			fracPart = fracPart[:4]
		}
		val, _ := strconv.Atoi(intPart + fracPart)
		return float64(val) / 10000.0
	}
	val, _ := strconv.Atoi(s)
	return float64(val)
}

func calcProb(N, K int) float64 {
	if K == 0 {
		return 0
	}
	U := N - K
	var numer float64
	// i=1
	if K >= 1 && U >= 2 {
		numer += float64(K) * float64(U) * float64(U-1) / 2.0
	}
	// i=2
	if K >= 2 && U >= 1 {
		numer += float64(K) * float64(K-1) / 2.0 * float64(U) * 2.0 / 3.0
	}
	// i=3
	if K >= 3 {
		numer += float64(K) * float64(K-1) * float64(K-2) / 6.0
	}
	denom := float64(N) * float64(N-1) * float64(N-2) / 6.0
	if denom == 0 {
		return 0
	}
	return numer / denom
}
